package com.app.service;
import com.app.dto.SharedExpenseDtos.*; import com.app.entity.*; import com.app.exception.*; import com.app.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*; import static java.util.stream.Collectors.*;
@Service @RequiredArgsConstructor @Transactional
public class SharedExpenseService {
 private final SharedExpenseGroupRepository groups; private final SharedGroupMemberRepository members; private final SharedExpenseRepository expenses; private final SharedExpensePayerRepository payers; private final SharedExpenseShareRepository shares; private final SharedSettlementRepository settlements; private final SharedExpenseActivityRepository activities; private final AccountRepository accounts; private final UserRepository users;
 public List<GroupDto> list(Long accountId,Long userId){ return groups.findAccessibleIncludingArchived(accountId,userId).stream().map(g->map(g,false)).toList(); }
 public GroupDto get(Long accountId,Long userId,Long id){ return map(groups.findAccessibleById(id,accountId,userId).orElseThrow(()->new ResourceNotFoundException("Shared expense group not found")),true); }
 public List<FriendBalanceDto> friends(Long accountId,Long userId){ Map<Long,FriendAccumulator> result=new LinkedHashMap<>(); for(SharedExpenseGroup g:groups.findAccessible(accountId,userId)){List<SharedGroupMember> groupMembers=members.findByGroupIdOrderByMemberName(g.getId());if(groupMembers.stream().noneMatch(m->m.getUser()!=null&&m.getUser().getId().equals(userId)))continue;GroupDto detail=map(g,true);Map<Long,BigDecimal> balances=detail.getBalances().stream().collect(toMap(BalanceDto::getMemberId,BalanceDto::getBalance));for(SharedGroupMember m:groupMembers){if(m.getUser()==null||m.getUser().getId().equals(userId)||!m.getActive())continue;FriendAccumulator a=result.computeIfAbsent(m.getUser().getId(),id->new FriendAccumulator(m.getUser()));a.sharedGroups++;a.balance=a.balance.add(balances.getOrDefault(m.getId(),BigDecimal.ZERO));}}return result.values().stream().map(a->FriendBalanceDto.builder().userId(a.user.getId()).name(a.user.getName()).email(a.user.getEmail()).mobile(a.user.getMobile()).sharedGroups(a.sharedGroups).balance(a.balance).build()).sorted(Comparator.comparing(FriendBalanceDto::getName)).toList(); }
 private static class FriendAccumulator { private final User user; private int sharedGroups; private BigDecimal balance=BigDecimal.ZERO; private FriendAccumulator(User user){this.user=user;} }
 public GroupDto createGroup(Long accountId,Long userId,GroupRequest r){ Account a=accounts.findById(accountId).orElseThrow(()->new ResourceNotFoundException("Account not found")); if(a.getAccountType()!=AccountType.INDIVIDUAL) throw new ValidationException("Shared expenses are available for personal accounts"); User u=users.findById(userId).orElseThrow(()->new ResourceNotFoundException("User not found")); SharedExpenseGroup g=groups.save(SharedExpenseGroup.builder().account(a).name(r.getName().trim()).createdBy(u).build()); members.save(SharedGroupMember.builder().group(g).user(u).memberName(u.getName()).email(u.getEmail()).mobile(u.getMobile()).build()); return map(g,true); }
 public GroupDto addMember(Long accountId,Long userId,Long groupId,MemberRequest r){ SharedExpenseGroup g=group(accountId,userId,groupId); SharedGroupMember m=members.save(SharedGroupMember.builder().group(g).memberName(r.getMemberName().trim()).email(r.getEmail()).mobile(r.getMobile()).build()); log(g,userId,SharedActivityType.MEMBER_ADDED,"MEMBER",m.getId(),"added member "+m.getMemberName()); return map(g,true); }
 public GroupDto updateGroup(Long accountId,Long userId,Long groupId,GroupUpdateRequest r){ SharedExpenseGroup g=group(accountId,userId,groupId); g.setName(r.getName().trim()); g.setActive(r.getActive()); g.setUpdatedAt(java.time.LocalDateTime.now()); groups.save(g); log(g,userId,SharedActivityType.GROUP_UPDATED,"GROUP",g.getId(),r.getActive()?"updated the group":"archived the group"); return map(g,true); }
 public GroupDto updateMember(Long accountId,Long userId,Long groupId,Long memberId,MemberUpdateRequest r){ SharedExpenseGroup g=group(accountId,userId,groupId); SharedGroupMember m=members.findByIdAndGroupId(memberId,groupId).orElseThrow(()->new ResourceNotFoundException("Group member not found")); m.setMemberName(r.getMemberName().trim()); m.setEmail(r.getEmail()); m.setMobile(r.getMobile()); m.setActive(r.getActive()); members.save(m); log(g,userId,SharedActivityType.MEMBER_UPDATED,"MEMBER",m.getId(),r.getActive()?"updated member "+m.getMemberName():"deactivated member "+m.getMemberName()); return map(g,true); }
 public GroupDto reverseExpense(Long accountId,Long userId,Long expenseId){ SharedExpense e=expenses.findByIdAndGroupAccountId(expenseId,accountId).orElseThrow(()->new ResourceNotFoundException("Shared expense not found")); if(e.getReversed()) throw new ValidationException("Expense is already reversed"); e.setReversed(true); e.setUpdatedAt(java.time.LocalDateTime.now()); expenses.save(e); log(e.getGroup(),userId,SharedActivityType.EXPENSE_REVERSED,"EXPENSE",e.getId(),"reversed expense "+e.getDescription()); return map(e.getGroup(),true); }
 public GroupDto reverseSettlement(Long accountId,Long userId,Long settlementId){ SharedSettlement s=settlements.findByIdAndGroupAccountId(settlementId,accountId).orElseThrow(()->new ResourceNotFoundException("Settlement not found")); if(s.getReversed()) throw new ValidationException("Settlement is already reversed"); s.setReversed(true); settlements.save(s); log(s.getGroup(),userId,SharedActivityType.SETTLEMENT_REVERSED,"SETTLEMENT",s.getId(),"reversed a settlement"); return map(s.getGroup(),true); }
 public GroupDto addExpense(Long accountId,Long userId,Long groupId,ExpenseRequest r){ SharedExpenseGroup g=group(accountId,userId,groupId); BigDecimal total=money(r.getTotalAmount()); List<AmountRow> payerRows=r.getPayers(); if(payerRows==null||payerRows.isEmpty()){if(r.getPaidByMemberId()==null)throw new ValidationException("Select at least one payer");AmountRow row=new AmountRow();row.setMemberId(r.getPaidByMemberId());row.setAmount(total);payerRows=List.of(row);} Map<Long,BigDecimal> paid=new LinkedHashMap<>();for(AmountRow x:payerRows){member(g,x.getMemberId());if(paid.put(x.getMemberId(),money(x.getAmount()))!=null)throw new ValidationException("Duplicate payer");}if(paid.values().stream().reduce(BigDecimal.ZERO,BigDecimal::add).compareTo(total)!=0)throw new ValidationException("Payer total must equal expense total"); List<SharedGroupMember> participants=r.getParticipantIds().stream().distinct().map(id->member(g,id)).toList(); if(participants.isEmpty()) throw new ValidationException("Select at least one participant"); Map<Long,BigDecimal> owed=r.getSplitType()==SharedSplitType.EQUAL?SharedSplitCalculator.equal(total,participants.stream().map(SharedGroupMember::getId).toList()):new LinkedHashMap<>(); if(r.getSplitType()==SharedSplitType.EXACT){if(r.getShares()==null)throw new ValidationException("Exact shares are required");for(AmountRow x:r.getShares()){member(g,x.getMemberId());if(owed.put(x.getMemberId(),money(x.getAmount()))!=null)throw new ValidationException("Duplicate member share");}if(!owed.keySet().equals(participants.stream().map(SharedGroupMember::getId).collect(toSet())))throw new ValidationException("Exact shares must match participants");}SharedSplitCalculator.requireTotal(total,owed.values()); User u=users.findById(userId).orElseThrow(); SharedExpense e=expenses.save(SharedExpense.builder().group(g).createdBy(u).description(r.getDescription().trim()).category(r.getCategory()).expenseDate(r.getExpenseDate()).totalAmount(total).splitType(r.getSplitType()).build());paid.forEach((id,amount)->payers.save(SharedExpensePayer.builder().expense(e).member(member(g,id)).paidAmount(amount).build()));owed.forEach((id,amount)->shares.save(SharedExpenseShare.builder().expense(e).member(member(g,id)).owedAmount(amount).build()));activities.save(SharedExpenseActivity.builder().group(g).actor(u).activityType(SharedActivityType.EXPENSE_ADDED).referenceType("EXPENSE").referenceId(e.getId()).message("Added expense: "+e.getDescription()).build());return map(g,true); }
 public GroupDto settle(Long accountId,Long userId,Long groupId,SettlementRequest r){ SharedExpenseGroup g=group(accountId,userId,groupId); if(r.getPaidByMemberId().equals(r.getPaidToMemberId())) throw new ValidationException("Settlement members must be different"); SharedSettlement s=settlements.save(SharedSettlement.builder().group(g).paidBy(member(g,r.getPaidByMemberId())).paidTo(member(g,r.getPaidToMemberId())).amount(money(r.getAmount())).settlementDate(r.getSettlementDate()).paymentMode(r.getPaymentMode()).notes(r.getNotes()).createdBy(users.findById(userId).orElseThrow()).build()); log(g,userId,SharedActivityType.SETTLEMENT_ADDED,"SETTLEMENT",s.getId(),"recorded a settlement"); return map(g,true); }
 private void log(SharedExpenseGroup g,Long userId,SharedActivityType type,String referenceType,Long referenceId,String message){activities.save(SharedExpenseActivity.builder().group(g).actor(users.findById(userId).orElseThrow()).activityType(type).referenceType(referenceType).referenceId(referenceId).message(message).build());}
 private SharedExpenseGroup group(Long a,Long userId,Long g){ return groups.findAccessibleById(g,a,userId).orElseThrow(()->new ResourceNotFoundException("Shared expense group not found")); } private SharedGroupMember member(SharedExpenseGroup g,Long id){ SharedGroupMember m=members.findByIdAndGroupId(id,g.getId()).orElseThrow(()->new ResourceNotFoundException("Group member not found")); if(!m.getActive()) throw new ValidationException("Group member is inactive"); return m; } private BigDecimal money(BigDecimal x){ return x.setScale(2,RoundingMode.UNNECESSARY); }
 private GroupDto map(SharedExpenseGroup g,boolean detail){ List<SharedGroupMember> ms=members.findByGroupIdOrderByMemberName(g.getId()); Map<Long,BigDecimal> b=ms.stream().collect(toMap(SharedGroupMember::getId,x->BigDecimal.ZERO)); if(detail){ payers.findByExpenseGroupIdAndExpenseReversedFalse(g.getId()).forEach(x->b.compute(x.getMember().getId(),(k,v)->v.add(x.getPaidAmount()))); shares.findByExpenseGroupIdAndExpenseReversedFalse(g.getId()).forEach(x->b.compute(x.getMember().getId(),(k,v)->v.subtract(x.getOwedAmount()))); settlements.findByGroupIdAndReversedFalse(g.getId()).forEach(x->{ b.compute(x.getPaidBy().getId(),(k,v)->v.add(x.getAmount())); b.compute(x.getPaidTo().getId(),(k,v)->v.subtract(x.getAmount())); }); }
  List<MemberDto> md=ms.stream().map(x->MemberDto.builder().id(x.getId()).userId(x.getUser()==null?null:x.getUser().getId()).memberName(x.getMemberName()).email(x.getEmail()).mobile(x.getMobile()).active(x.getActive()).build()).toList(); List<BalanceDto> bd=detail?ms.stream().map(x->BalanceDto.builder().memberId(x.getId()).memberName(x.getMemberName()).balance(b.get(x.getId())).build()).toList():List.of(); List<ExpenseDto> ed=detail?expenses.findByGroupIdOrderByExpenseDateDescIdDesc(g.getId()).stream().map(x->ExpenseDto.builder().id(x.getId()).description(x.getDescription()).category(x.getCategory()).expenseDate(x.getExpenseDate()).totalAmount(x.getTotalAmount()).splitType(x.getSplitType()).reversed(x.getReversed()).paidBy(payers.findByExpenseGroupIdAndExpenseReversedFalse(g.getId()).stream().filter(p->p.getExpense().getId().equals(x.getId())).map(p->p.getMember().getMemberName()).distinct().collect(joining(", "))).build()).toList():List.of(); List<ActivityDto> ad=detail?activities.findTop100ByGroupIdOrderByCreatedAtDesc(g.getId()).stream().map(x->ActivityDto.builder().id(x.getId()).activityType(x.getActivityType().name()).message(x.getMessage()).actorName(x.getActor().getName()).createdAt(x.getCreatedAt()).build()).toList():List.of(); return GroupDto.builder().id(g.getId()).name(g.getName()).active(g.getActive()).members(md).expenses(ed).balances(bd).activities(ad).build(); }
}
